<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class MenuItem extends Model{protected $guarded=[];protected function casts():array{return['price'=>'decimal:2','tax_rate'=>'decimal:4','service_charge_rate'=>'decimal:4','stock_quantity_per_sale'=>'decimal:4','send_to_kitchen'=>'boolean','is_bar_item'=>'boolean','is_active'=>'boolean'];}public function property(){return $this->belongsTo(Property::class);}public function outlet(){return $this->belongsTo(Outlet::class);}public function category(){return $this->belongsTo(MenuCategory::class,'menu_category_id');}public function inventoryItem(){return $this->belongsTo(InventoryItem::class);}public function modifiers(){return $this->belongsToMany(MenuModifier::class,'menu_item_modifier');}public function recipe(){return $this->hasOne(Recipe::class);}}
